sp_widget.client_script:
api.controller = function($scope, spUtil) {
  var c = this;
  c.loadedWidgets = new Array(c.data.widgets.length);
  c.ready = false;
  var count = 0;
  var total = c.data.widgets.length;
angular.forEach(c.data.widgets, function(widgetId, index) {
    spUtil.get(widgetId).then(function(response) {
      c.loadedWidgets[index] = response;
      count++;
      if (count === total) {
        c.ready = true;
      }
    });
  });
};

sp_widget.css:
.hdi-page-container {
  max-width: 900px;
  margin: 0 auto;
  padding: 8px 0 20px 0;
}
.hdi-widget-row {
  margin-bottom: 12px;
  scroll-margin-top: 60px;
}


.hdi-loading {
  padding: 60px 0;
  color: #888;
}


.hdi-loading i {
  color: #0c67a9;
}


.hdi-loading p {
  margin-top: 10px;
  font-size: 14px;
}
